nodes=sorted(unique(data['nodes']))
edges=data['edges']
links=[]
for edge in edges:
    u=edge['u']
    v=edge['v']
    if u!=v:
        links=links+[[u,v],[v,u]]
counts=[]
total=0
for node in nodes:
    count=0
    for a in nodes:
        for b in nodes:
            if node<a and a<b and [node,a] in links and [node,b] in links and [a,b] in links:
                count=count+1
    counts=counts+[{'id':node,'triangles':count}]
    total=total+count
result={'main':{'total':total,'nodes':counts}}
